<?php
declare(strict_types=1);
require_once __DIR__.'/../_core/bootstrap.php';require_once __DIR__.'/../_core/CommerceOrders.php';
use BYPCMS\Core\CommerceOrders;
header('Cache-Control: no-store');header('X-Robots-Tag: noindex, nofollow');
if(($config['app']['installation_type']??'platform')==='client'){http_response_code(403);exit('Кабинет покупателя доступен на платформе BYPCMS.');}
$commerce=new CommerceOrders($db,$config,BYPCMS_ROOT);$_SESSION['customer_csrf']??=bin2hex(random_bytes(32));
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$next=(string)($_GET['next']??$_POST['next']??'/account/');if(strlen($next)>2500||strpbrk($next,"\r\n\0\\")!==false||!preg_match('~^/(?:order/?|account/(?:order\.php)?)(?:\?[^#]*)?$~D',$next))$next='/account/';
$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 if(!hash_equals($_SESSION['customer_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Сессия формы истекла. Обновите страницу и повторите действие.');
 $action=(string)($_POST['action']??'');
 if($action==='logout'){unset($_SESSION['customer_id']);session_regenerate_id(true);$_SESSION['customer_csrf']=bin2hex(random_bytes(32));$next='/account/';}
 elseif(in_array($action,['login','register'],true)){
  $commerce->limit('login:'.($_SERVER['REMOTE_ADDR']??''),10,900);$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190||strlen($password)>1024)throw new RuntimeException('Проверьте email и пароль.');
  if($action==='register'){\BYPCMS\Core\CommerceLegal::validate($_POST,false);$name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>190||strlen($password)<12)throw new RuntimeException('Укажите имя и пароль от 12 символов.');if($db->one('SELECT id FROM byp_customer_accounts WHERE email=?',[$email]))throw new RuntimeException('Не удалось зарегистрироваться. Если аккаунт уже существует, используйте вход.');$db->pdo()->beginTransaction();$id=$db->insert('INSERT INTO byp_customer_accounts(email,name,password_hash,created_at) VALUES(?,?,?,NOW())',[$email,$name,password_hash($password,PASSWORD_DEFAULT)]);\BYPCMS\Core\CommerceLegal::record($db,$id,null,false);$db->pdo()->commit();}
  else{$row=$db->one('SELECT id,password_hash FROM byp_customer_accounts WHERE email=?',[$email]);if(!$row||!password_verify($password,$row['password_hash']))throw new RuntimeException('Неверный email или пароль.');$id=(int)$row['id'];}
  session_regenerate_id(true);$_SESSION['customer_id']=$id;$_SESSION['customer_csrf']=bin2hex(random_bytes(32));
 }else throw new RuntimeException('Действие не поддерживается.');
 header('Location: '.$next);exit;
}catch(Throwable $exception){if($db->pdo()->inTransaction())$db->pdo()->rollBack();$error=$exception instanceof RuntimeException||$exception instanceof InvalidArgumentException?$exception->getMessage():'Не удалось выполнить действие. Повторите позже.';}
$customer=empty($_SESSION['customer_id'])?null:$db->one('SELECT id,name,email FROM byp_customer_accounts WHERE id=?',[(int)$_SESSION['customer_id']]);
$page=max(1,min(10000,(int)($_GET['page']??1)));$orders=$customer?$db->all('SELECT o.*,d.kind,d.amount_minor,d.payment_state,d.fulfillment_state,l.id AS license_id,l.status AS license_status,l.valid_until FROM byp_customer_orders o LEFT JOIN byp_commerce_orders d ON d.order_id=o.id LEFT JOIN byp_license_order_links k ON k.order_id=o.id LEFT JOIN byp_license_registry l ON l.id=k.license_id WHERE o.customer_id=? ORDER BY o.id DESC LIMIT 20 OFFSET '.(($page-1)*20),[$customer['id']]):[];
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Личный кабинет — BYPCMS</title><link rel="stylesheet" href="/account/account.css"></head><body><main><header><a href="/">BYPCMS</a><a href="/order/">Новый заказ</a><a href="/contacts/">Контакты и реквизиты</a><?php if($customer):?><form method="post"><input type="hidden" name="csrf" value="<?= $e($_SESSION['customer_csrf']) ?>"><button name="action" value="logout">Выйти</button></form><?php endif ?></header><h1>Личный кабинет</h1><?php if($error):?><p class="error" role="alert"><?= $e($error) ?></p><?php endif ?>
<?php if(!$customer):?><p>Войдите, чтобы сохранить заказ, оплатить лицензию и получить свою сборку.</p><div class="grid"><?php foreach(['login'=>'Войти','register'=>'Регистрация']as $action=>$title):?><section><h2><?= $title ?></h2><form method="post"><input type="hidden" name="csrf" value="<?= $e($_SESSION['customer_csrf']) ?>"><input type="hidden" name="next" value="<?= $e($next) ?>"><input type="hidden" name="action" value="<?= $action ?>"><?php if($action==='register'):?><label>Имя<input name="name" required maxlength="190" autocomplete="name" value="<?= $e($_POST['name']??'') ?>"></label><?php endif ?><label>Email<input name="email" type="email" required autocomplete="email" value="<?= $e($_POST['email']??'') ?>"></label><label>Пароль<input name="password" type="password" required <?= $action==='register'?'minlength="12"':'' ?> autocomplete="<?= $action==='register'?'new-password':'current-password' ?>"></label><?php if($action==='register'):?><input type="hidden" name="legal_version" value="<?= $e(\BYPCMS\Core\CommerceLegal::VERSION) ?>"><label class="check"><input type="checkbox" required name="accept_privacy" value="1"> Даю <a href="/legal/consent/" target="_blank" rel="noopener">согласие на обработку данных</a>, прочитал <a href="/legal/privacy/" target="_blank" rel="noopener">политику</a>.</label><?php endif ?><button><?= $title ?></button></form></section><?php endforeach ?></div>
<?php else:?><p><?= $e($customer['name']) ?> · <?= $e($customer['email']) ?></p><h2>Мои заказы</h2><?php foreach($orders as $o):?><article><h3>Заказ №<?= (int)$o['id'] ?> · <?= $e(ucfirst($o['edition'])) ?></h3><p><?= $e($o['domain']) ?> · <?= $o['license_term']==='annual'?'1 год':'Пожизненная' ?></p><p>Модули: <?= $e(implode(', ',json_decode($o['modules'],true)?:[])) ?></p><?php if($o['kind']):?><p><?= $e(number_format($o['amount_minor']/100,2,',',' ')) ?> ₽<?= $o['kind']==='inquiry'?' — лицензионная часть, услуги по согласованию':'' ?></p><p><?= $e(['paid'=>'Оплата подтверждена','pending'=>'Ожидает оплаты','canceled'=>'Платёж отменён'][$o['payment_state']]??$o['payment_state']) ?></p><a class="button" href="/account/order.php?id=<?= (int)$o['id'] ?>">Открыть заказ</a><?php else:?><p>Исторический тестовый заказ · <?= $e($o['status']) ?></p><?php if($o['status']==='test_confirmed'):?><a href="/account/purchase.php?id=<?= (int)$o['id'] ?>">Открыть выданную покупку</a><?php endif ?><?php endif ?><?php if($o['license_id']&&$o['license_term']==='annual'&&in_array($o['license_status'],['active','renewal','expired'],true)&&!\BYPCMS\Core\CommerceAccess::blocked($db->pdo(),(int)$o['license_id'])):?><p>Лицензия до <?= $e($o['valid_until']) ?> · <a href="/order/?renewal=<?= (int)$o['license_id'] ?>">Продлить на год</a></p><?php endif ?></article><?php endforeach ?><?php if(!$orders):?><p>Заказов пока нет. <a href="/order/">Выбрать редакцию</a></p><?php endif ?><nav aria-label="Страницы заказов"><?php if($page>1):?><a href="?page=<?= $page-1 ?>">Назад</a><?php endif ?><?php if(count($orders)===20):?><a href="?page=<?= $page+1 ?>">Далее</a><?php endif ?></nav><?php endif ?><footer><a href="/legal/offer/">Условия покупки</a> · <a href="/legal/privacy/">Персональные данные</a> · <a href="/legal/refunds/">Возвраты</a></footer></main></body></html>
